import {makePrimitives} from './geometry.js';
import {cellsFor,advance,kern,inkOffset} from './typography.js';
const escape=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
export function primitives(state,glyph){const style={...state,...state.overrides?.[glyph]};return makePrimitives(cellsFor(state,glyph),state.columns,style).map(p=>({...p,scaleX:(style.width??100)/100}));}
export function drawGlyph(ctx,state,glyph,x=0,y=0,cell=1){ctx.save();ctx.translate(x,y);ctx.scale(cell,cell);ctx.fillStyle=ctx.strokeStyle=state.color;ctx.lineCap='round';ctx.lineJoin='round';for(const p of primitives(state,glyph)){ctx.save();ctx.scale(p.scaleX,1);if(p.type==='polygon'){ctx.beginPath();p.points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fill()}else if(p.type==='ring'){ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.arc(p.x,p.y,p.inner,0,Math.PI*2,true);ctx.fill('evenodd')}else if(p.type==='rect')ctx.fillRect(p.x,p.y,p.width,p.width);else if(p.type==='circle'){ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}else{ctx.lineWidth=p.width;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x2,p.y2);ctx.stroke()}ctx.restore()}ctx.restore();}
function elements(state,glyph){return primitives(state,glyph).map(p=>{let shape;if(p.type==='polygon')shape=`<polygon points="${p.points.map(v=>v.join(',')).join(' ')}"/>`;else if(p.type==='ring')shape=`<circle cx="${p.x}" cy="${p.y}" r="${(p.r+p.inner)/2}" fill="none" stroke="${state.color}" stroke-width="${p.r-p.inner}"/>`;else if(p.type==='rect')shape=`<rect x="${p.x}" y="${p.y}" width="${p.width}" height="${p.width}"/>`;else if(p.type==='circle')shape=`<circle cx="${p.x}" cy="${p.y}" r="${p.r}"/>`;else shape=`<path d="M${p.x} ${p.y}L${p.x2} ${p.y2}" fill="none" stroke="${state.color}" stroke-width="${p.width}" stroke-linecap="round"/>`;return `<g transform="scale(${p.scaleX},1)">${shape}</g>`}).join('');}
export function glyphSVG(state,glyph){const width=state.columns*(state.overrides?.[glyph]?.width??100)/100+1;return `<svg xmlns="http://www.w3.org/2000/svg" width="${width*40}" height="${(state.rows+1)*40}" viewBox="-.5 -.5 ${width} ${state.rows+1}" fill="${state.color}"><title>${escape(glyph)}</title>${elements(state,glyph)}</svg>`;}
export function textSVG(state){
 const t=state.tester||{size:48,leading:1.4,align:'left',bg:'light'},lines=(state.previewText||' ').split('\n'),step=(c,next)=>advance(state,c)+kern(state,c,next||'');
 const widths=lines.map(line=>[...line].reduce((n,c,i)=>n+step(c,[...line][i+1]),0)),width=Math.max(1,...widths),height=state.rows+(lines.length-1)*state.rows*t.leading;
 return `<svg xmlns="http://www.w3.org/2000/svg" width="${(width+1)*t.size/state.rows}" height="${(height+1)*t.size/state.rows}" viewBox="-.5 -.5 ${width+1} ${height+1}" fill="${state.color}">${lines.map((line,row)=>{let x=t.align==='center'?(width-widths[row])/2:t.align==='right'?width-widths[row]:0;return [...line].map((c,i)=>{const result=`<g transform="translate(${x+inkOffset(state,c)},${row*state.rows*t.leading})">${elements(state,c)}</g>`;x+=step(c,[...line][i+1]);return result}).join('')}).join('')}</svg>`;
}
